import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';import{partitionOwnedSelectMotion,ownedSelectMotionProblems,MENU_MOTION_SYMBOL}from'../scripts/api-owned-motion-context.mjs';import {createPublicFactoryContext} from './api-public-node-context.mjs';
