const fixture=await createPublicFactoryContext(core,spec=>import(spec),{providers:[core.importProvidersFrom(api.MatLegacyMenuModule)]});try{
const Type=api.MatLegacyMenu,injector=fixture.element.injector,zone={run:f=>f(),runOutsideAngular:f=>f(),onStable:new core.EventEmitter()},config={xPosition:'after',yPosition:'below',overlapTrigger:false};
const capture=runFactory(()=>new Type(fixture.element.element,zone,config,fixture.element.detector),core.Injector,core.runInInjectionContext,{injector,captureStack:true});assert.equal(capture.outcome,'returned',capture.error);
const packageDir=new URL('./node_modules/@ngx-compat/material-legacy/',import.meta.url),files={core:fileURLToPath(new URL('fesm2022/ngx-compat-material-legacy-legacy-core.mjs',packageDir)),caller:fileURLToPath(new URL('fesm2022/ngx-compat-material-legacy-legacy-menu.mjs',packageDir))};
const observe=(T=Type,exports=api)=>partitionOwnedSelectMotion(capture.requests,core,owned,layout,material,T,files,runFactory,injector,capture.value,MENU_MOTION_SYMBOL,{familyExports:exports});
const result=observe();assert.deepEqual(ownedSelectMotionProblems(result.observation,MENU_MOTION_SYMBOL),[]);assert.equal(result.observation.constructor_owner.public_subclass_export,'MatLegacyMenu');assert.equal(result.observation.cases.length,9);
assert.throws(()=>observe(Type,{...api,MatLegacyMenu:class Foreign{}}),/public subclass identity/);
const old=Object.getPrototypeOf(Type.prototype);try{Object.setPrototypeOf(Type.prototype,{});assert.throws(()=>observe(),/public subclass identity/);}finally{Object.setPrototypeOf(Type.prototype,old);}
capture.value.ngOnDestroy();console.log(JSON.stringify({actual_packed_motion_observer:true,cases:result.observation.cases.length,classified_requests:result.observation.classified_requests,public_subclass_identity:true,wrong_export_rejected:true,wrong_prototype_rejected:true,observation:result.observation}));
}finally{fixture.close();}

